src/ai.js.after:
const act = action => {
    const auditAction = { ...action, factionId: id };
    const auditBefore = globalThis.expeditionReinforcementObserver?.beforeCommand(state, auditAction);
    const auditResult = command(state, auditAction);
    globalThis.expeditionReinforcementObserver?.afterCommand(state, auditAction, auditBefore, auditResult);
    return auditResult;
  };

